def solve_math_problem(n=15):
    numbers = tuple(range(1, n + 1))
    squares = {i * i for i in range(2, int(math.sqrt(2 * n)) + 2)}
    neighbors = {x: [y for y in numbers if y != x and x + y in squares] for x in numbers}
    def search(path, remaining):
        if not remaining:
            return path
        for nxt in sorted(neighbors[path[-1]], key=lambda z: len(neighbors[z])):
            if nxt in remaining:
                found = search(path + [nxt], remaining - {nxt})
                if found:
                    return found
        return None
    for start in numbers:
        found = search([start], set(numbers) - {start})
        if found:
            return found[0] + found[-1]
    return None

