import itertools, math

def solve_math_problem(digits=3):
    low = 10 ** (digits - 1)
    high = 10 ** digits
    def is_prime(n):
        if n < 2:
            return False
        for d in range(2, int(math.sqrt(n)) + 1):
            if n % d == 0:
                return False
        return True
    primes = set()
    max_root = int((high - 1) ** (1 / 3)) + 2
    for root in range(1, max_root + 1):
        cube = root ** 3
        if not (low <= cube < high):
            continue
        for perm in itertools.permutations(str(cube)):
            if perm[0] == '0':
                continue
            value = int(''.join(perm))
            if low <= value < high and is_prime(value):
                primes.add(value)
    return len(primes)

